!function(e){function t(t){for(var r,i,n=t[0],o=t[1],d=t[2],g=0,s=[];g<n.length;g++)i=n[g],Object.prototype.hasOwnProperty.call(m,i)&&m[i]&&s.push(m[i][0]),m[i]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(e[r]=o[r]);for(c&&c(t);s.length;)s.shift()();return p.push.apply(p,d||[]),a()}function a(){for(var e,t=0;t<p.length;t++){for(var a,i=p[t],n=!0,o=1;o<i.length;o++)a=i[o],0!==m[a]&&(n=!1);n&&(p.splice(t--,1),e=r(r.s=i[0]))}return e}function r(t){if(i[t])return i[t].exports;var a=i[t]={i:t,l:!1,exports:{}};return e[t].call(a.exports,a,a.exports,r),a.l=!0,a.exports}var i={},m={10:0},p=[];r.m=e,r.c=i,r.d=function(e,t,a){r.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:a})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,t){if(1&t&&(e=r(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var a=Object.create(null);if(r.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)r.d(a,i,function(t){return e[t]}.bind(null,i));return a},r.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(t,"a",t),t},r.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},r.p="";var n=window.webpackJsonp=window.webpackJsonp||[],o=n.push.bind(n);n.push=t,n=n.slice();for(var d=0;d<n.length;d++)t(n[d]);var c=o;p.push([94,0]),a()}({94:function(e,t,a){"use strict";a.r(t);var r=a(0);Object(r.a)("de","army",a(95),a(1))},95:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/1、Sd Kfz 4/1型半履带装甲火箭炮车","description":"<p>二战初期，为了有效打击集群进攻的敌军，德军将一种箱式火箭弹发射装置安装在251系列车体上，改装成中型自行火箭弹发射车，这型火箭炮车最早是在251B型车体上改装，后来改用251D型车进行改装，该炮车并保留了前、后机枪，车体两侧各挂装3部单管WGr 42型280mm或320mm火箭弹发射装置（全车一共挂装6部）。</p><p>251/1型半履带装甲火箭炮车在东线战场上主要用作对苏军进行大面积杀伤和对固定火力点的摧毁，尽管火箭弹射击准确率很低，但由于弹着点的大范围覆盖，火箭弹内装的又是高爆炸药或凝固汽油，因此杀伤威力还是相当大的。</p><p>而Sd Kfz 4/1半履带装甲火箭炮车则是在1943年才装备德军部队的，它是用Sd Kfz 4/1半履带装甲车进行改装，将1门10管分2排并列组合的42型150mm火箭炮架在车体上方而成。该型炮车主要装备德军的独立旅（每个旅装备4辆），由独立旅军官直接指挥。</p><p>另外，德军也有少量在半履带装甲车体上安装18管80mm双排式火箭发射器的火箭炮车。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}炮车四视图（线图）{{image}}imgs/de/army/de_army_avhtv2511&Kfz4_11.jpg","description":"<h6>251/1 B型半履带装甲火箭炮车<br>Sd Kfz 251/1 Ausf B “Stuka Zu Fuss”</h6><p>该型车体两侧安装的3组钢管框架可挂载280mm高爆火箭弹箱（一次性使用的木箱）或320mm燃烧火箭弹箱（多次性使用的钢箱）；高爆火箭弹内装40公斤TNT高爆炸药，其射程为1900米，而燃烧火箭弹内装50升凝固汽油，射程为2200米。</p><p>炮车有确定火箭弹发射方向的瞄准用标杆（装设在发动机舱盖前侧两端位置），火箭弹的发射方向要依靠车体的转向来确定，射程可通过钢框底部钢板的调节齿调整火箭弹箱的角度来实现。</p><p>该炮车标准载员7人，有驾驶员1人和车长1 人，其余5人负责搬运和发射火箭弹。由于车厢内要放置火箭弹箱，车载人员只能身处驾驶室内和车门外。由于火箭弹发射时会产生高温火焰，所以发射前车载人员要撒到车外，在安全距离外用专用的起爆箱控制点火。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_12.jpg","description":"<h6>251/1 D型半履带装甲火箭炮车</h6><p>在251的各型车体中，改装为火箭弹发射车数量最多的是D型车，该型炮车虽然仍保留前、后机枪架，但一般只会装备一挺MG42型机枪。</p>","caption":""},{"image":"{{text}}炮车四视图1（彩图）{{image}}imgs/de/army/de_army_avhtv2511&Kfz4_13.jpg","description":"<h6>Sd Kfz 4/1型半履带装甲火箭炮车</h6><p>Sd Kfz 4/1半履带装甲炮车自重7.1t，长6m，宽2.2m，高2.5m；最大时速40Km/h ，最大行程 130km。该型车于1943年4月开始量产，至1944年共生产了近600辆，其中改装为火箭炮车有300辆（其它为弹药运输车）。</p><p>改装后的Sd Kfz 4/1半履带装甲火箭炮车重量增加至8.5t，高度为3.05m，在车体后部改装为火箭发射转台，转台上方安装了一门150mm口径、10管二排并列的火箭炮，发射转台可以左右旋转270°，发射仰角为-12°～+80°，车厢内放20发火箭弹，作战时有专门的弹药运输车跟随；装填火箭弹时要打开后车门，站在伸出的踏板上进行装填。转台的操纵和火箭弹的发射均由载员在车内控制，由于火箭炮安装在车体后方，火箭弹发射时的尾焰不会喷射到车体，且因车内有装甲保护，所以炮车载员在发射时不必离车。</p><p>该炮车还安装有一挺MG42(或MG34）机枪以作自卫用。</p>","caption":""},{"image":"{{text}}炮车四视图2（彩图）{{image}}imgs/de/army/de_army_avhtv2511&Kfz4_14.jpg","description":"<p>德军另有一款Sd Kfz 4/1型半履带装甲火箭炮车安装的是双层18管80mm火箭炮。</p>","caption":""}],"part2title":"战场上的251/1、Sd Kfz 4/1型半履带装甲火箭炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_21.jpg","description":"1945年1月，东线战场波兰地区，德军第16装甲师的一辆251/1 D型半履带装甲火箭炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_22.jpg","description":"1945年3月，德国东普鲁士地区，德军第11独立旅的一辆Sd Kfz 4/1半履带装甲火箭炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_23.jpg","description":"1944年8月，法国诺曼底地区，德军一辆不明单位的Sd Kfz 4/1半履带装甲火箭炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_24.jpg","description":"东线苏联战场，正向前线进发的德军一队251/1半履带装甲火箭炮车。注意此时炮车两侧发射框架内上尚未装上火箭弹发射箱。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_25.jpg","description":"东线苏联战场上的一辆251/1 C型半履带装甲火箭炮车。注意此炮车是焊接车体，车上安装的是发射280mm高爆火箭弹的木箱，车上士兵前面是一挺无防盾的MG34机枪。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_26.jpg","description":"东线苏联战场上的德军一辆251/1 C半履带装甲火箭炮车。注意此炮车是铆接车体，车上安装的是发射320mm燃烧火箭弹的钢质箱，前置机枪已更换为新式的MG42型。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_27.jpg","description":"一组德军251/1 C型半履带装甲火箭炮车的炮组成员在进行火箭弹箱安装的照片。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_28.jpg","description":"东线苏联战场上的一辆251/1 B型半履带装甲火箭炮车。炮车停在一林边土路上，一名德军军官正在向车组作指示。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_29.jpg","description":"1944年夏天，东线战场，德国某武装党卫军装甲师的一辆251/1 C型半履带装甲火箭炮车。注意该炮车已装上火箭弹，车上已换上MG42型机枪。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_30.jpg","description":"1944年8月13日，波兰华沙诺沃里普基地区，一辆德军的251/1 C型火箭发射车正在发射火箭弹炮击老城区。注意火箭弹发射时，车上人员已全部撒离。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_31.jpg","description":"一队德军Sd Kfz 4/1半履带装甲火箭炮车正在进行战术转移，为了躲避空袭和对方炮火的反击，火箭炮车每发射一次，就会马上从原发射阵地转移到命令下达的新发射阵地。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_32.jpg","description":"安装在德军Sd Kfz 4/1半履带装甲火箭炮车上的42型150mm火箭炮，实战证明，150mm火箭炮在对付集群进攻与摧毁火力点上是十分有效的。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_33.jpg","description":"一辆德军Sd Kfz 4/1半履带装甲火箭炮车的弹药手正在进行火箭弹装填。此图可清楚看到炮车上安装火箭炮的转台。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_34.jpg","description":"1944年12月，埃菲尔山脉，在营部指挥官下达开火命令后，德军火箭发射营的Sd Kfz 4/1半履带装甲火箭炮车上的42型150mm火箭炮开始一次齐射，图中可见第一发炮弹刚刚射出。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_35.jpg","description":"一辆正在行进的德军Sd Kfz 4/1半履带装甲火箭炮车，注意该炮车的火箭炮已装上火箭弹。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_36.jpg","description":"1944年，阿登前线，德军Sd Kfz 4/1半履带装甲火箭炮车到达了他们的阵地，图片中可以清晰看到后方火箭发射车和舱室的轮廓形状。","caption":""},{"image":"imgs/de/army/de_army_avhtv2511&Kfz4_37.jpg","description":"1943年3月，正在装载带尾翼稳定炮弹的18管双排80mm多管火箭炮。如武装党卫军第521火箭发射营就装备了10门80mm多管发射炮车，之后其番号变更为第506火箭发射营。","caption":""}]}')}});